const normalize = word => word.normalize('NFKD').replace(/[^\x00-\x7F]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
export const THEME_CATEGORIES = definitions.map(([id,label])=>[id,label]);
export const THEME_WORD_PACKS = Object.fromEntries(definitions.map(([id,,text])=>[id,[...new Set(text.split(/\s+/).map(normalize).filter(word=>word.length>=2&&word.length<=44))].sort()]));
for(const [id,words] of Object.entries(THEME_WORD_PACKS))THEME_WORD_PACKS[id]=[...new Set([...words,...(VOCABULARY_ADDITIONS[id]||[])])].sort();
const historicAliases = new Set(HISTORICAL_DEFINITIONS.flatMap(([id])=>THEME_WORD_PACKS[id]));
for(const [id] of HISTORICAL_DEFINITIONS){
  const words=THEME_WORD_PACKS[id];
  const givenNames=HISTORICAL_GIVEN_NAMES.filter(given=>words.some(full=>full.startsWith(given)&&full.length>given.length&&historicAliases.has(full.slice(given.length))));
  THEME_WORD_PACKS[id]=[...new Set([...words,...givenNames])].sort();
}
export const THEME_SETTING_IDS = THEME_CATEGORIES.map(([id])=>`packTheme_${id}`);
